{% var project_value = filters.project; %}
{% var include_children = cint(filters.include_child_projects || 0); %}
{% var project_label = project_value || __("All Projects"); %}
{% if (project_value && include_children) { %}
  {% project_label = project_label + " (" + __("including child projects") + ")"; %}
{% } %}

{% var period = (filters.period || "Month"); %}
{% var period_start = null; %}
{% var period_end = null; %}
{% if (period === "Range") { %}
  {% period_start = filters.from_date; %}
  {% period_end = filters.to_date; %}
{% } else { %}
  {% var date_value = filters.date; %}
  {% if (date_value) { %}
    {% var date_obj = moment(date_value, frappe.defaultDateFormat); %}
    {% if (period === "Week") { %}
      {% period_start = moment(date_obj).isoWeekday(1).format(frappe.defaultDateFormat); %}
      {% period_end = moment(period_start, frappe.defaultDateFormat).add(6, "days").format(frappe.defaultDateFormat); %}
    {% } else if (period === "Month") { %}
      {% period_start = moment(date_obj).startOf("month").format(frappe.defaultDateFormat); %}
      {% period_end = moment(date_obj).endOf("month").format(frappe.defaultDateFormat); %}
    {% } else { %}
      {% period_start = moment(date_obj).format(frappe.defaultDateFormat); %}
      {% period_end = period_start; %}
    {% } %}
  {% } %}
{% } %}

{% var project_totals = {}; %}
{% var total_hours = 0; %}
{% for (var i = 0; i < data.length; i++) { %}
  {% var row = data[i] || {}; %}
  {% var hours = flt(row.hours || 0, 2); %}
  {% total_hours = total_hours + hours; %}
  {% if (row.project) { %}
    {% project_totals[row.project] = (project_totals[row.project] || 0) + hours; %}
  {% } %}
{% } %}

<div class="simple-report">
  <div class="simple-header">
    <div class="simple-title">{{ __("Single Booking Service Report") }}</div>
    <div class="simple-meta">{{ __("Project (Identifier)") }}: {{ project_label }}</div>
    <div class="simple-meta">{{ __("Service Period") }}: {% if (period_start && period_end) { %}{{ frappe.datetime.str_to_user(period_start, false, true) }} - {{ frappe.datetime.str_to_user(period_end, false, true) }}{% } else { %}-{% } %}</div>
  </div>

  <table class="simple-table">
    <thead>
      <tr>
        <th>{{ __("Date") }}</th>
        <th>{{ __("Project") }}</th>
        <th>{{ __("Employee") }}</th>
        <th>{{ __("Note") }}</th>
        <th class="text-right">{{ __("Hours") }}</th>
      </tr>
    </thead>
    <tbody>
      {% if (data && data.length) { %}
        {% for (var i = 0; i < data.length; i++) { %}
          {% var row = data[i] || {}; %}
          {% var user_display = row.employee_name || row.user || ""; %}
          <tr>
            <td>{{ row.date ? frappe.datetime.str_to_user(row.date, false, true) : "" }}</td>
            <td>{{ row.project || "" }}</td>
            <td>{{ user_display }}</td>
            <td>{{ row.note || "" }}</td>
            <td class="text-right">{{ format_number(flt(row.hours || 0, 2), null, 2) }}</td>
          </tr>
        {% } %}
      {% } else { %}
        <tr>
          <td colspan="5" class="text-muted">{{ __("No bookings found.") }}</td>
        </tr>
      {% } %}
    </tbody>
  </table>

  <div class="simple-summary">
    <div class="summary-title">{{ __("Project Summary") }}</div>
    <table class="summary-table">
      <tbody>
        {% var project_keys = Object.keys(project_totals).sort(); %}
        {% if (project_keys.length) { %}
          {% for (var k = 0; k < project_keys.length; k++) { %}
            {% var project_key = project_keys[k]; %}
            <tr>
              <td class="label">{{ project_key }}</td>
              <td class="value text-right">{{ format_number(flt(project_totals[project_key] || 0, 2), null, 2) }} h</td>
            </tr>
          {% } %}
        {% } else { %}
          <tr>
            <td class="label">{{ __("No projects") }}</td>
            <td class="value text-right">0.00 h</td>
          </tr>
        {% } %}
      </tbody>
    </table>
    <div class="total-hours">{{ __("Total Hours") }}: {{ format_number(flt(total_hours || 0, 2), null, 2) }} h</div>
  </div>
</div>

<div id="footer-html" class="visible-pdf">
  <div class="page-number">
    {{ __("Page {0} of {1}", ["<span class='page'></span>", "<span class='topage'></span>"]) }}
  </div>
</div>

css:
@page {
  size: A4;
  margin: 12mm 10mm 12mm 10mm;
}

.print-format {
  font-family: Arial, Helvetica, sans-serif;
  font-size: 9pt;
  color: #111111;
}

.simple-header {
  text-align: center;
  margin-bottom: 6mm;
}

.simple-title {
  font-size: 11pt;
  font-weight: bold;
  margin-bottom: 2mm;
}

.simple-meta {
  font-size: 9pt;
  margin-top: 1mm;
}

.simple-table {
  width: 100%;
  border-collapse: collapse;
}

.simple-table th,
.simple-table td {
  border: 1px solid #333333;
  padding: 2px 3px;
  vertical-align: top;
}

.simple-table th {
  background: #f4f4f4;
  font-weight: bold;
}

.simple-table td {
  height: 12px;
}

.simple-summary {
  margin-top: 6mm;
  border-top: 1px solid #999999;
  padding-top: 4mm;
  font-size: 9pt;
}

.simple-summary .summary-title {
  font-weight: bold;
  margin-bottom: 2mm;
}

.summary-table {
  width: 100%;
  border-collapse: collapse;
}

.summary-table td {
  padding: 1px 0;
}

.summary-table td.label {
  width: 70%;
  font-weight: bold;
}

.summary-table td.value {
  width: 30%;
}

.total-hours {
  margin-top: 2mm;
  font-weight: bold;
}

.page-number {
  text-align: center;
  font-size: 8pt;
  color: #444444;
}
